pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // test contract is owner of c
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint128).max);

        // fund c through its payable fallback (raw call avoids `.fallback` syntax)
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);
        assertEq(address(c).balance, amount);

        // a non-owner tries to withdraw everything: must not change c's balance
        vm.prank(actor);
        (bool okCall, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        okCall;

        // general rule: a non-owner can never change c's balance via withdrawAll
        assertTrue(address(c).balance == amount, "non-owner must not drain the contract");
    }
}

