pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: a strictly positive contract balance and any actor that is not the owner.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // owner is set to the deployer (this test contract)
        amount = bound(amount, 1, type(uint256).max / 2);

        // Fund the contract so a withdrawal has a real effect.
        vm.deal(address(c), amount);

        // Drive c through the changed entry point withdrawAll from the (fuzzed) non-owner.
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a non-owner's withdrawAll must revert (owner-only); the mutant lets
        // any caller succeed and drain address(c).balance to 0.
        assertTrue(!ok && address(c).balance == amount && c.depositsCount() == 0);
    }
}

