pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address depositor, address caller) public {
        // wide admissible domain: any depositor, any caller (including the owner), any amount
        vm.assume(depositor != address(c));
        vm.assume(caller != address(c));
        amount = bound(amount, 1, type(uint128).max);

        // fund the contract through its public payable fallback (also bumps depositsCount)
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool depOk,) = address(c).call{value: amount}("");
        assertTrue(depOk);
        assertTrue(c.depositsCount() == 1);

        // attempt to withdraw everything from a fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Universal rule: if withdrawAll succeeded, the whole balance must have been
        // transferred out (balance drained to zero) AND the caller must be the owner.
        assertTrue(!ok || (address(c).balance == 0 && caller == c.owner()));
    }
}

