pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 fund, uint256 amount) public {
        fund = bound(fund, 2, type(uint128).max);
        amount = bound(amount, 1, fund - 1);

        address owner = address(0xdead);

        vm.deal(address(this), fund);
        (bool okFund, ) = address(c).call{value: fund}("");
        assertTrue(okFund);

        vm.deal(owner, 1 wei);
        vm.prank(owner);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.withdraw.selector, amount));
        assertTrue(ok);

        assertEq(address(c).balance, fund - amount);
    }
}

