pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint256).max / 4);

        // deposit via the fallback through the low-level call surface
        vm.deal(address(this), amount);
        (bool okDeposit, ) = address(c).call{value: amount}("");
        assertTrue(okDeposit);

        // first full withdrawal by the owner (the test contract deployed c, so it is the owner)
        c.withdrawAll();
        uint256 before = address(c).balance;

        // if the first call drained everything, a second withdrawAll cannot move any ether
        c.withdrawAll();
        assertTrue(address(c).balance == before);
    }
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	receive() external payable {}
	function test(uint amount) public {
		require(amount > 0);
		require(address(this).balance >= amount);
		(bool okFwd, ) = address(c).call{value: amount}("");
		require(okFwd);
		require(address(c).balance >= amount);
		bool reverted = false;
		try c.withdraw(amount) {
			reverted = false;
		} catch {
			reverted = true;
		}
		assert(reverted);
	}
}

