contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(address _target, uint _value, bytes calldata _data) external {
		// Drive the call at an address guaranteed to make the inner call fail:
		// this test contract declares no receive/fallback, so any call to it reverts.
		require(_target == address(this));
		require(_value == 0);
		bool s;
		(s, ) = address(c).call(
			abi.encodeWithSelector(C.sendMoney.selector, _target, _value, _data)
		);
		// On P: the inner call fails, sendMoney reverts, so the low-level call returns false.
		// On M: the failure check is deleted, sendMoney completes normally, so s is true.
		assert(!s);
	}
}

contract InvMutTest {
